function dashboard(){const a=alerts(),block=state.donors.filter(d=>d.status==='blocked');const avail=state.doses.filter(x=>x.status==='available'&&canUse(donor(x.donor))).length,res=state.doses.filter(x=>x.status==='reserved'&&canUse(donor(x.donor))).length,hold=state.doses.filter(x=>['available','reserved','quarantine'].includes(x.status)&&(!canUse(donor(x.donor))||x.status==='quarantine')).length,total=avail+res+hold;
return heading('תמונת מצב','כל המידע, ההחלטות והמעקב — במקום אחד.',btn('ייצוא דוח','exportSummary','download')+btn('הוספת תורם','addDonor','plus',true))+`${block.length?`<div class="banner">${icon('alert')}<div><strong>${block.length===1?'תורם אחד חסום לשימוש':block.length+' תורמים חסומים לשימוש'}.</strong> מנות ועוברים הקשורים אליו מסומנים למעקב. שימוש חדש במנות חסום במערכת.</div><button class="btn small" data-nav="blocks">לרשימת החסימות</button></div>`:''}`+metrics()+`<div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>מאגר התורמים</h2><p>אישור, מלאי ונתרמות לכל תורם</p></div><button class="btn text small" data-nav="donors">לכל התורמים</button></div>${filterBar(false)}${donorTable(true)}</section><section class="panel"><div class="panel-head"><h2>פעילות אחרונה</h2><span class="last-update">יומן מקומי</span></div>${[...state.audit].reverse().slice(0,3).map(a=>`<div class="activity"><div class="activity-icon">${icon(a.action.includes('חסימ')?'ban':'file',15)}</div><div><p>${esc(a.action)}</p><small>${fmt(a.time)} · ${esc(a.by)}</small></div></div>`).join('')}</section></div><aside class="dashboard-aside"><section class="panel"><div class="panel-head"><h2>דורש תשומת לב</h2>${badge(a.length+' התראות',a.length?'wait':'good')}</div>${a.length?a.slice(0,4).map(x=>`<div class="attention-item" data-action="donor" data-id="${x.id}"><div class="attention-symbol ${x.kind==='wait'?'amber':''}">${icon(x.kind==='bad'?'ban':'clock',16)}</div><div><b>${esc(x.title)}</b><p>${esc(x.body)}</p><small>${esc(x.date)}</small></div></div>`).join(''):'<div class="empty">אין התראות פתוחות</div>'}</section><section class="panel"><div class="panel-head"><h2>התפלגות המלאי</h2></div><div class="donut-section"><div class="donut" style="background:conic-gradient(var(--teal) 0 ${total?avail/total*100:0}%,#98b9b1 0 ${total?(avail+res)/total*100:0}%,#d9e1df 0 100%)"><div class="donut-value">${total}<small>מנות ביחידה</small></div></div><div class="legend"><div><i class="swatch"></i>זמינות<b>${avail}</b></div><div><i class="swatch" style="background:#98b9b1"></i>שמורות<b>${res}</b></div><div><i class="swatch" style="background:#d9e1df"></i>בהמתנה / חסימה<b>${hold}</b></div></div></div></section><section class="panel"><div class="panel-head"><h2>עדכון משרד הבריאות</h2>${icon('shield')}</div><div style="padding:0 23px 23px"><p class="label-note">הזנה ידנית או ייבוא קובץ מאומת. אין חיבור חי למשרד הבריאות.</p><p class="last-update">עדכון מתועד אחרון: ${fmt(state.mohUpdates.at(-1)?.date)}</p><button class="btn small" data-action="mohImport">${icon('upload',15)}קליטת עדכון</button></div></section></aside></div>`}
function filterBar(origins=true){return `<div class="filters"><div class="search">${icon('search',16)}<input id="search" aria-label="חיפוש" placeholder="חיפוש לפי קוד תורם, כינוי או בנק…" value="${esc(filters.q)}"></div><select id="statusFilter" aria-label="סינון סטטוס"><option value="">כל הסטטוסים</option>${[['active','מאושר לשימוש'],['blocked','חסום'],['pending','ממתין / ללא אישור']].map(([v,l])=>`<option value="${v}" ${filters.status===v?'selected':''}>${l}</option>`).join('')}</select>${origins?`<select id="originFilter" aria-label="מקור תורם"><option value="">כל המקורות</option>${Object.entries(orig).map(([v,l])=>`<option value="${v}" ${filters.origin===v?'selected':''}>${l}</option>`).join('')}</select>`:''}</div>`}
function filteredDonors(){return state.donors.filter(d=>(!filters.q||[d.id,d.alias,d.bank,d.external].some(v=>v.toLowerCase().includes(filters.q.toLowerCase())))&&(!filters.origin||d.origin===filters.origin)&&(!filters.status||(filters.status==='active'?canUse(d):filters.status==='pending'?d.status==='pending'||d.status==='active'&&!currentApproval(d):d.status===filters.status)))}
function donorTable(compact=false){const list=filteredDonors();return `<div id="donorTable"><div class="table-wrap"><table><thead><tr><th>תורם</th><th>מקור</th><th>סטטוס שימוש</th><th>מנות במלאי</th><th>נתרמות פעילות</th>${!compact?'<th>השתמשו בתורם</th><th>עוברים מוקפאים</th><th>הגעה ליחידה</th>':''}<th></th></tr></thead><tbody>${list.slice(0,compact?6:9999).map(d=>`<tr class="clickrow ${d.status==='blocked'?'blocked-stripe':''}" data-action="donor" data-id="${esc(d.id)}"><td><div class="donor-id"><div class="donor-avatar">${icon(d.origin==='local'?'users':'building',17)}</div><div><span class="id">${esc(d.id)}</span><small>${esc(d.alias)}</small></div></div></td><td>${esc(orig[d.origin])}<small>${esc(d.bank)}</small></td><td>${donorStatus(d)}</td><td>${ds(d.id).filter(v=>['available','reserved','quarantine'].includes(v.status)).length}<small>מתוך ${ds(d.id).length} שנקלטו</small></td><td>${countRecipients(d.id,true)}<small>במאגר המקומי</small></td>${!compact?`<td>${historicCount(d.id)}</td><td>${em(d.id).reduce((a,e)=>a+frozen(e),0)}</td><td>${fmt(d.arrival)}</td>`:''}<td><button class="btn text small" aria-label="פתיחת כרטיס ${esc(d.id)}" data-action="donor" data-id="${esc(d.id)}">${icon('chevron',15)}</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">לא נמצאו תורמים התואמים לסינון</td></tr>'}</tbody></table></div><div class="table-footer"><span>${Math.min(list.length,compact?6:list.length)} מתוך ${list.length} תורמים</span><span>לחיצה על שורה לפתיחת כרטיס</span></div></div>`}
function table(head,rows){return `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(c=>`<tr>${c.map(v=>`<td>${v??'—'}</td>`).join('')}</tr>`).join(''):`<tr><td class="empty" colspan="${head.length}">טרם נוספו רשומות</td></tr>`}</tbody></table></div>`}
function panel(title,body,actions=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2><div class="actions">${actions}</div></div>${body}</section>`}
function dosesTable(list){return table(['מנה / אצווה','תורם','הקפאה','קליטה ביחידה','מיקום','סוג הכנה','סטטוס','נתרמת / שימוש','פעולה'],list.map(v=>{const u=state.uses.find(u=>u.dose===v.id),d=donor(v.donor);return [`<span class="id">${esc(v.id)}</span><small>${esc(v.batch)}</small>`,donorLink(v.donor),fmt(v.frozen),fmt(v.received),esc(v.location),esc(v.quality),d.status==='blocked'&&['available','reserved','quarantine'].includes(v.status)?badge('חסומה עם התורם','bad'):badge(doseStatus[v.status],v.status==='available'?'good':v.status==='quarantine'?'wait':'neutral'),u?`${pLink(u.recipient)}<small>${esc(u.type)} · ${fmt(u.date)}</small>`:v.recipient?pLink(v.recipient):'—',['available','reserved','quarantine'].includes(v.status)?`<div class="actions">${['available','reserved'].includes(v.status)?`<button class="btn small" data-action="use" data-id="${esc(v.id)}">רישום שימוש</button>`:''}<button class="btn small" data-action="manageDose" data-id="${esc(v.id)}">ניהול מנה</button></div>`:'—']}))}
function useTable(list){return table(['תאריך טיפול','נתרמת','תורם','מנה','סוג טיפול','מחזור טיפול','תאריך הקפאה'],list.map(u=>[fmt(u.date),pLink(u.recipient),donorLink(u.donor),`<span class="id">${esc(u.dose)}</span>`,badge(u.type,'blue'),esc(u.cycle),fmt(state.doses.find(x=>x.id===u.dose)?.frozen)]))}
function embryoTable(list){return table(['נתרמת','תורם','מחזור / הקפאה','נוצרו','נוצלו','הושמדו','נותרו קפואים','מיקום','פעולה'],list.map(e=>[pLink(e.recipient),donorLink(e.donor),`${esc(e.cycle)}<small>${fmt(e.date)}</small>`,e.created,e.used,e.discarded,`${frozen(e)}${donor(e.donor)?.status==='blocked'?'<small class="error-note">תורם חסום · נדרש בירור</small>':''}`,esc(e.location),`<button class="btn small" data-action="editEmbryo" data-id="${esc(e.id)}">עדכון מלאי</button>`]))}
function approvalTable(list){return table(['תורם','החלטה','תאריך החלטה','תאריך קבלה','תוקף עד','אסמכתה','פירוט'],[...list].reverse().map(a=>[donorLink(a.donor),badge(a.decision==='approved'?'אישור':a.decision==='blocked'?'חסימה':'המתנה',a.decision==='blocked'?'bad':a.expires<today()?'wait':a.decision==='approved'?'good':'wait'),fmt(a.date),fmt(a.received),fmt(a.expires),esc(a.ref),`<span style="display:block;max-width:270px;white-space:normal;line-height:1.5">${esc(a.note)}</span>`]))}
function transferTable(list){return table(['תאריך','תורם','תנועה','בנק מקור / יעד','מספר מנות','אסמכתה','מזהי מנות'],[...list].reverse().map(t=>[fmt(t.date),donorLink(t.donor),badge(t.direction==='in'?'קליטה ליחידה':'העברה החוצה',t.direction==='in'?'good':'blue'),esc(t.bank),t.doseIds.length,esc(t.ref),`<span title="${esc(t.doseIds.join(', '))}">${esc(t.doseIds.slice(0,2).join(', '))}${t.doseIds.length>2?' +'+(t.doseIds.length-2):''}</span>`]))}
function birthTable(list){return table(['לידה','נתרמת','תורם','מחזור טיפול','מידע בריאותי','תאריך דיווח','הערות','פעולה'],list.map(b=>[fmt(b.date),pLink(b.recipient),donorLink(b.donor),esc(b.cycle),badge(health[b.health],['review','finding'].includes(b.health)?'wait':'neutral'),fmt(b.reported),`<span style="white-space:normal;display:block;max-width:260px">${esc(b.note)}</span>`,`<button class="btn small" data-action="editBirth" data-id="${esc(b.id)}">עדכון דיווח</button>`]))}
function paymentTable(list){return table(['תאריך','תורם','מפגש / אצווה','סכום','אסמכתה','הערות'],[...list].reverse().map(p=>[fmt(p.date),donorLink(p.donor),esc(p.session),money(p.amount),esc(p.ref),esc(p.note)]))}
function content(){switch(view){case'dashboard':return dashboard();case'donors':return heading('מאגר התורמים','כרטיס תורם אחד. תמונה מלאה של כל תרומה.',btn('ייצוא תורמים','exportDonors','download')+btn('הוספת תורם','addDonor','plus',true))+panel('כל התורמים',filterBar()+donorTable());case'doses':return heading('מלאי מנות הזרע','עקיבות לפי מזהה מנה, תאריך הקפאה, מיקום ונתרמת.',btn('רישום שימוש','use','vial')+btn('קליטת מנות','addDose','plus',true))+`<div class="notice">כל מנה מקבלת מזהה ייחודי. רישום שימוש בודק בזמן הפעולה את חסימת התורם, תוקף האישור, זמינות המנה והשיוך לנתרמת.</div>`+panel('כל המנות',`<div class="filters"><div class="search">${icon('search',16)}<input id="doseSearch" placeholder="חיפוש לפי מנה, תורם, אצווה או מיקום" aria-label="חיפוש מנות"></div><select id="doseStatus" aria-label="סטטוס מנה"><option value="">כל הסטטוסים</option>${Object.entries(doseStatus).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></div><div id="doseResults">${dosesTable(state.doses)}</div>`);case'recipients':return recipientsPage();case'donor':return donorPage();case'recipient':return recipientPage();case'approvals':return heading('אישורים ועדכונים','תיעוד החלטות, תאריכי תוקף ועדכונים שהתקבלו ממשרד הבריאות.',btn('קליטת עדכון מקובץ','mohImport','upload')+btn('תיעוד החלטה','addApproval','plus',true))+`<div class="notice">אין חיבור אוטומטי למשרד הבריאות. כל אסמכתה במסך זה היא רישום ידני; נתוני הפתיחה והאישורים המוצגים הם סינתטיים.</div>`+panel('החלטות ואישורים',approvalTable(state.approvals))+panel('יומן קליטת עדכונים',table(['תאריך קבלה','אסמכתה','רשומות','הערה'],[...state.mohUpdates].reverse().map(m=>[fmt(m.date),esc(m.ref),m.rows,esc(m.note)])));case'blocks':return blocksPage();case'transfers':return heading('העברות בין בנקים','מקור, יעד, תאריכים ומזהי המנות בכל העברה.',btn('תיעוד העברה','addTransfer','plus',true))+panel('היסטוריית העברות',transferTable(state.transfers));case'reports':return reportsPage();case'settings':return settingsPage();default:return dashboard()}}
function recipientsPage(){return heading('נתרמות וטיפולים','קשר מתועד בין התורם, המנה, הטיפול והתוצאה.',btn('רישום לידה','addBirth','baby')+btn('רישום עוברים','addEmbryo','vial')+btn('פתיחת תיק נתרמת','addRecipient','plus',true))+panel('תיקי נתרמות',table(['קוד נתרמת','שם הדגמה','מצב תיק','תורמים קשורים','טיפולים מתועדים','עוברים מוקפאים','פעולה'],state.recipients.map(p=>{const ids=new Set([...state.uses.filter(x=>x.recipient===p.id).map(x=>x.donor),...state.doses.filter(x=>x.recipient===p.id).map(x=>x.donor),...state.embryos.filter(x=>x.recipient===p.id).map(x=>x.donor)]);return [pLink(p.id),esc(p.name),badge(recStatus[p.status],p.status==='active'?'good':'neutral'),[...ids].map(donorLink).join(' '),state.uses.filter(x=>x.recipient===p.id).length,state.embryos.filter(x=>x.recipient===p.id).reduce((a,e)=>a+frozen(e),0),`<button class="btn small" data-action="editRecipient" data-id="${esc(p.id)}">עדכון תיק</button>`]})))+panel('יומן טיפולים',useTable(state.uses),btn('רישום שימוש במנה','use','plus'))+panel('מלאי עוברים מדווח',embryoTable(state.embryos))+panel('לידות ומעקב בריאותי',birthTable(state.births))}
function blocksPage(){const list=state.donors.filter(d=>d.status==='blocked');return heading('חסימות ומעקב','החלטת חסימה נשמרת עם תאריך, סיבה והשפעה על מלאי ונתרמות.',btn('רישום חסימה','block','ban',true))+`<div class="notice bad">חסימת תורם מונעת רישום שימוש והעברה החוצה של מנות. עוברים קיימים מסומנים לבירור קליני; המערכת אינה מקבלת החלטה רפואית לגביהם.</div>`+list.map(d=>{const k=blockedImpact(d);return panel(`${esc(d.id)} · ${esc(d.alias)} ${badge('חסום','bad')}`,`<div class="detail-body"><p class="help-text">${esc(d.blockReason)}</p><div class="kv-grid"><div><div class="kv-label">מועד חסימה</div><div class="kv-value">${fmt(d.blockedDate)}</div></div><div><div class="kv-label">מנות מושפעות ביחידה</div><div class="kv-value">${k.doses}</div></div><div><div class="kv-label">נתרמות קשורות</div><div class="kv-value">${k.recipients}</div></div><div><div class="kv-label">עוברים מוקפאים</div><div class="kv-value">${k.embryos}</div></div><div><div class="kv-label">השתמשו בתורם בעבר</div><div class="kv-value">${historicCount(d.id)}</div></div><div><div class="kv-label">עדיין בטיפול</div><div class="kv-value">${countRecipients(d.id,true)}</div></div></div></div>`,btn('תיק תורם','donor','file',false,d.id)+btn('תיעוד שחרור חסימה','unblock','shield',false,d.id))}).join('')+(!list.length?panel('תורמים חסומים','<div class="empty">אין תורמים חסומים במאגר</div>'):'')+panel('התראות אישורים',alerts().filter(a=>a.kind==='wait').map(a=>`<div class="attention-item" data-action="donor" data-id="${esc(a.id)}">${icon('clock')}<div><b>${esc(a.title)}</b><p>${esc(a.body)} · ${esc(a.date)}</p></div></div>`).join('')||'<div class="empty">אין התראות אישורים נוספות</div>')}
function donorPage(){const d=donor(selected);if(!d)return '<div class="empty">התורם לא נמצא</div>';const a=currentApproval(d),k=blockedImpact(d);let body='';
 const tabs=[['overview','פרטי תורם'],['doses','מנות'],['recipients','נתרמות וטיפולים'],['embryos','עוברים ולידות'],['approvals','אישורים וחסימות'],['transfers','העברות'],['payments','תרומות ותשלומים']];
 if(detailTab==='overview'){const vals=[['קוד מקומי',d.id],['כינוי',d.alias],['מקור התורם',orig[d.origin]],['בנק מקור',d.bank],['מדינה',d.country],['קוד בבנק המקור',d.external||'—'],['שנת לידה',d.birthYear||'—'],['תאריך הגעה ליחידה',fmt(d.arrival)],['אישור תקף עד',fmt(a?.expires)],['תאריך אישור אחרון',fmt(a?.date)],['מועד חסימה',fmt(d.blockedDate)],['נתרמות שהשתמשו בעבר',historicCount(d.id)]];body=`<div class="detail-body"><div class="kv-grid">${vals.map(([l,v])=>`<div><div class="kv-label">${l}</div><div class="kv-value">${esc(v)}</div></div>`).join('')}</div><h3 class="subheading">הערות בתיק</h3><p class="help-text">${esc(d.notes||'לא הוזנו הערות')}</p><div class="privacy-screen"><div><div class="kv-label">פרטים מזהים חסויים · הדגמה בלבד</div><div class="kv-value">${reveal?`${esc(d.name||'לא נמסר')} · ${esc(d.identity||'לא נמסר')}`:'הפרטים מוסתרים בתצוגה הרגילה'}</div></div><button class="btn small" data-action="reveal">${icon('eye',16)}${reveal?'הסתרת פרטים':'הצגת פרטי הדגמה'}</button></div><p class="label-note">הסתרת התצוגה אינה הרשאת גישה. בגרסה זו כל הנתונים נמצאים בדפדפן; אין להזין מידע מזהה אמיתי.</p></div>`}
 if(detailTab==='doses')body=`<div class="detail-body actions">${btn('קליטת מנות','addDose','plus',true,d.id)}${btn('רישום שימוש','use','vial',false,d.id)}</div>`+dosesTable(ds(d.id));
 if(detailTab==='recipients')body=table(['נתרמת','מצב תיק','מספר טיפולים','מנות שמורות','עוברים קפואים'],linkedPatients(d.id).map(p=>[pLink(p.id),badge(recStatus[p.status],p.status==='active'?'good':'neutral'),us(d.id).filter(x=>x.recipient===p.id).length,ds(d.id).filter(x=>x.recipient===p.id&&x.status==='reserved').length,em(d.id).filter(x=>x.recipient===p.id).reduce((a,e)=>a+frozen(e),0)]))+`<div class="panel-head"><h2>טיפולים מתועדים</h2></div>`+useTable(us(d.id));
 if(detailTab==='embryos')body=`<div class="detail-body actions">${btn('רישום עוברים','addEmbryo','plus',true,d.id)}${btn('רישום לידה','addBirth','baby',false,d.id)}</div>`+embryoTable(em(d.id))+`<div class="panel-head"><h2>לידות ובריאות הצאצאים</h2></div>`+birthTable(state.births.filter(x=>x.donor===d.id));
 if(detailTab==='approvals')body=`<div class="detail-body actions">${btn('תיעוד החלטה','addApproval','plus',true,d.id)}${d.status==='blocked'?btn('תיעוד שחרור חסימה','unblock','shield',false,d.id):btn('חסימת שימוש','block','ban',false,d.id)}</div>`+approvalTable(state.approvals.filter(x=>x.donor===d.id));
 if(detailTab==='transfers')body=`<div class="detail-body actions">${btn('תיעוד העברה','addTransfer','plus',true,d.id)}</div>`+transferTable(state.transfers.filter(x=>x.donor===d.id));
 if(detailTab==='payments')body=`<div class="detail-body"><div class="kv-grid"><div><div class="kv-label">מנות מקומיות שנקלטו</div><div class="kv-value">${d.origin==='local'?ds(d.id).length:'תורם שאינו מקומי'}</div></div><div><div class="kv-label">מפגשי תרומה מתועדים</div><div class="kv-value">${d.origin==='local'?new Set(ds(d.id).map(x=>x.batch)).size:'—'}</div></div><div><div class="kv-label">סך תשלומים מתועדים</div><div class="kv-value">${money(state.payments.filter(x=>x.donor===d.id).reduce((a,p)=>a+p.amount,0))}</div></div></div><p class="label-note">מספר המנות מחושב ממזהי המנות; מספר התרומות מחושב מאצוות מקומיות ייחודיות.</p><div class="actions">${btn('רישום תשלום','addPayment','wallet',true,d.id)}</div></div>`+paymentTable(state.payments.filter(x=>x.donor===d.id));
 return heading(`${esc(d.id)} <span style="font-weight:400;color:#788e91">/ ${esc(d.alias)}</span>`,'תיק תורם · נתונים מקומיים ועדכונים מתועדים',btn('חזרה למאגר','backDonors')+btn('עריכת פרטים','editDonor','edit',true,d.id))+`${d.status==='blocked'?`<div class="notice bad">${icon('ban')} חסום מתאריך ${fmt(d.blockedDate)} · ${esc(d.blockReason)}<br>${k.doses} מנות במלאי ו־${k.embryos} עוברים מסומנים למעקב.</div>`:''}<div class="metrics">${metric('מנות ביחידה',k.doses,`${ds(d.id).length} מנות שנקלטו לאורך הזמן`,'vial')}${metric('נתרמות עדיין בטיפול',countRecipients(d.id,true),`${historicCount(d.id)} השתמשו בתורם בעבר`,'heart')}${metric('עוברים מוקפאים',k.embryos,'לפי מלאי מדווח ביחידה','baby')}${metric('תשלומים לתורם',money(state.payments.filter(x=>x.donor===d.id).reduce((a,p)=>a+p.amount,0)),'סך תשלומים שנרשמו','wallet')}</div><section class="panel"><div class="detail-top"><div><b>${esc(d.alias)}</b><div class="highlights"><span>${esc(orig[d.origin])}</span><span>${esc(d.bank)}</span></div></div>${donorStatus(d)}</div><div class="detail-tabs">${tabs.map(([id,l])=>`<button data-tab="${id}" class="${detailTab===id?'active':''}">${l}</button>`).join('')}</div>${body}</section>`}
function reportsPage(){return heading('דוחות ונתונים','דוחות תקופתיים, מלאי נוכחי וגיבוי נתוני ההדגמה.',btn('הדפסה / PDF','print','file'))+`<div class="panel"><div class="panel-head"><h2>תקופת הדיווח</h2><span class="last-update">מסנן לטיפולים, לידות, העברות ותשלומים</span></div><div class="filters"><label class="label-note">מתאריך <input type="date" id="reportFrom" value="${today().slice(0,4)}-01-01"></label><label class="label-note">עד תאריך <input type="date" id="reportTo" value="${today()}"></label><button class="btn small" data-action="periodSummary">הצגת סיכום תקופתי</button></div><div id="periodResult"></div></div><div class="report-grid">${[['תמונת מלאי ותורמים','מלאי נוכחי, נתרמות פעילות, אישורים ועוברים. תמונת המצב אינה מסוננת לפי תקופה.','exportDonors','users'],['יומן טיפולים','מנה, תורם, נתרמת, תאריך הקפאה, תאריך טיפול וסוג טיפול בתקופה שנבחרה.','exportUses','heart'],['דוח חסימות','כל התורמים החסומים כעת, סיבת החסימה, מנות ועוברים הקשורים אליהם.','exportBlocks','ban'],['מלאי עוברים','מספר עוברים שנותרו בהקפאה לפי תורם, נתרמת ומחזור טיפול; מלאי נוכחי.','exportEmbryos','vial'],['לידות ומעקב בריאותי','לידות שדווחו בתקופה שנבחרה, כולל מקור ההקשר הטיפולי ומצב המידע הבריאותי.','exportBirths','baby'],['תשלומים לתורמים','פירוט תשלומים לתורמים בתקופה שנבחרה, מפגש תרומה ואסמכתה.','exportPayments','wallet'],['העברות בין בנקים','תנועות נכנסות ויוצאות, בנק מקור או יעד ומזהי מנות בתקופה שנבחרה.','exportTransfers','transfer'],['יומן פעולות','כל הפעולות שתועדו בדפדפן זה. זהו יומן הדגמה מקומי וניתן לשינוי.','exportAudit','clock'],['גיבוי מלא לעריכה','קובץ JSON עם כל הרשומות וההגדרות. ניתן לשחזר אותו בהגדרות המערכת.','backup','download']].map(([t,p,a,ic])=>`<section class="report-card">${icon(ic,24)}<h2>${t}</h2><p>${p}</p>${btn(a==='backup'?'הורדת גיבוי JSON':'הורדת CSV',a,'download')}</section>`).join('')}</div>`}
function settingsPage(){return heading('הגדרות והתאמה','נקודת התחלה שתוכל לעצב ולפתח לפי צורכי הבנק.')+`<div class="split">${panel('זהות היחידה ועיצוב',`<form id="settingsForm" class="detail-body"><div class="form-grid">${field('institution','שם מוסד','text',state.settings.institution,true)}${field('unit','שם יחידה','text',state.settings.unit,true)}${field('accent','צבע מוביל','color',state.settings.accent,true)}</div><div class="actions" style="margin-top:23px"><button class="btn primary" type="submit">שמירת התאמה</button></div></form>`)}${panel('נתונים וגיבוי',`<div class="detail-body"><p class="help-text">נתוני ההדגמה נשמרים בדפדפן ובמכשיר זה בלבד. ייצוא גיבוי מאפשר להעביר את העבודה למכשיר אחר. אין סנכרון בין בתי חולים.</p><div class="actions">${btn('ייצוא גיבוי JSON','backup','download')}${btn('שחזור מגיבוי','restore','upload')}${btn('איפוס נתוני הדגמה','reset','settings')}</div><p class="label-note">שחזור או איפוס מחליפים את כל הנתונים המקומיים לאחר אישור מפורש.</p></div>`)}</div>${panel('מה כולל אב־הטיפוס',`<div class="detail-body"><div class="notice">מיועד לבחינת מבנה ותהליכי עבודה עם מידע סינתטי בלבד. אין להזין נתונים אמיתיים של תורמים, מטופלות או ילדים.</div><ul class="list-bullet"><li>תורמים ומזהים פנימיים וחיצוניים, מקור מקומי או יבוא והיסטוריית העברות.</li><li>עקיבות מנות, טיפולים, עוברים, לידות, תשלומים ואישורים.</li><li>בדיקות חסימה ותוקף בעת רישום שימוש והעברה החוצה.</li><li>התאמת שם היחידה וצבע, ייצוא CSV וגיבוי מלא לשחזור.</li></ul><h3 class="subheading">לפני מעבר למערכת בית חולים</h3><p class="help-text">יש להשלים שרת ובסיס נתונים מאובטחים, הפרדת הרשאות וזהויות, הפרדת מוסדות, יומן ביקורת בלתי ניתן לשינוי, גיבוי מרכזי, ניהול מסמכים, חיבור רשמי למשרד הבריאות ובדיקת תהליכים ואבטחת מידע מוסדית. בדיקות הדפדפן באב־הטיפוס אינן בקרת אבטחה בשרת.</p>${btn('מקורות והנחות עבודה','help','help')}</div>`)}`}
function field(name,label,type='text',value='',required=true,wide=false,extra=''){return `<div class="field ${wide?'wide':''}"><label for="f-${name}">${label}${required?' *':''}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" ${required?'required':''}>${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}>`}</div>`}
function selectField(name,label,opts,value='',required=true,wide=false){return `<div class="field ${wide?'wide':''}"><label for="f-${name}">${label}${required?' *':''}</label><select name="${name}" id="f-${name}" ${required?'required':''}>${opts.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`}).join('')}</select></div>`}
const donorOpts=(onlyLocal=false)=>[['','בחירת תורם'],...state.donors.filter(d=>!onlyLocal||d.origin==='local').map(d=>[d.id,`${d.id} · ${d.alias}${canUse(d)?'':' · '+(d.status==='blocked'?'חסום':'ממתין לאישור')}`])];
const patientOpts=()=>[['','בחירת נתרמת'],...state.recipients.map(p=>[p.id,p.id+' · '+p.name])];
function modal(title,body,submit=null,sub='מילוי רשומה בנתוני הדגמה בלבד'){ $('#overlay').innerHTML=`<div class="modal-bg"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${sub}</p></div><button class="close" data-close aria-label="סגירה">${icon('close')}</button></div>${submit?'<form id="modalForm">':''}<div class="modal-body"><div id="formError" class="form-error" hidden></div>${body}</div><div class="modal-footer"><button type="button" class="btn" data-close>${submit?'ביטול':'סגירה'}</button>${submit?'<button class="btn primary" type="submit">שמירת רשומה</button>':''}</div>${submit?'</form>':''}</section></div>`; $$('[data-close]').forEach(b=>b.onclick=closeModal);$('#overlay').onclick=e=>{if(e.target.classList.contains('modal-bg'))closeModal()};if(submit)$('#modalForm').onsubmit=async e=>{e.preventDefault();try{await submit(Object.fromEntries(new FormData(e.target)));}catch(err){$('#formError').hidden=false;$('#formError').textContent=err.message;$('#formError').scrollIntoView({block:'nearest'})}}; setTimeout(()=>$('#overlay input,#overlay select,#overlay textarea,#overlay [data-close]')?.focus(),30)}
function closeModal(){ $('#overlay').innerHTML='';mohPreview=null }
function done(action,message='הרשומה נשמרה'){closeModal();save(action);toast(storageWarning||message)}
function requireCondition(c,message){if(!c)throw Error(message)}
function past(date,label='התאריך'){requireCondition(date<=today(),label+' אינו יכול להיות בעתיד')}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(new Date(s+'T12:00:00'))&&new Date(s+'T12:00:00').toISOString().slice(0,10)===s}
function donorForm(id){const edit=id?donor(id):null,d=edit||{};modal(edit?'עריכת פרטי תורם':'הוספת תורם',`<div class="notice">תורם חדש נפתח במצב ממתין לאישור. שימוש יתאפשר לאחר תיעוד אישור תקף.</div><div class="form-grid">${field('id','קוד תורם פנימי','text',d.id||'',true,false,edit?'readonly':'maxlength="40"')}${field('alias','כינוי','text',d.alias||'')}${selectField('origin','מקור',Object.entries(orig),d.origin||'local')}${field('bank','בנק מקור','text',d.bank||state.settings.institution)}${field('country','מדינה','text',d.country||'ישראל')}${field('external','קוד בבנק המקור','text',d.external||'',false)}${field('arrival','תאריך הגעה ליחידה','date',d.arrival||today())}${field('birthYear','שנת לידה','number',d.birthYear||'',false,false,'min="1900" max="'+new Date().getFullYear()+'"')}${field('name','שם חסוי לדוגמה בלבד','text',d.name||'',false)}${field('identity','מזהה חסוי לדוגמה בלבד','text',d.identity||'',false)}${field('notes','הערות','textarea',d.notes||'',false,true)}</div>`,f=>{f.id=f.id.trim();requireCondition(/^[A-Za-z0-9_-]{2,40}$/.test(f.id),'קוד תורם יכיל אותיות באנגלית, ספרות, מקף או קו תחתון בלבד (2–40 תווים).');requireCondition(edit||!donor(f.id),'קוד התורם כבר קיים');past(f.arrival,'תאריך ההגעה');if(f.origin!=='local')requireCondition(f.external.trim(),'יש לציין קוד בבנק המקור');const clash=state.donors.some(x=>x.id!==f.id&&x.bank===f.bank&&x.external&&x.external===f.external);requireCondition(!clash,'קוד זה כבר קיים בבנק המקור');const updated={...d,...f,birthYear:num(f.birthYear),status:d.status||'pending'};if(edit)state.donors[state.donors.indexOf(edit)]=updated;else state.donors.push(updated);done((edit?'עודכנו פרטי תורם ':'נפתח תיק תורם ')+f.id)})}
function recipientForm(id){const p=id?patient(id):null;modal(p?'עדכון תיק נתרמת':'פתיחת תיק נתרמת',`<div class="form-grid">${field('id','קוד נתרמת','text',p?.id||'',true,false,p?'readonly':'maxlength="40"')}${field('name','שם לדוגמה','text',p?.name||'')}${selectField('status','מצב תיק',Object.entries(recStatus),p?.status||'active')}${field('opened','תאריך פתיחת תיק','date',p?.opened||today())}${field('notes','הערות','textarea',p?.notes||'',false,true)}</div>`,f=>{f.id=f.id.trim();requireCondition(/^[A-Za-z0-9_-]{2,40}$/.test(f.id),'קוד נתרמת יכיל אותיות באנגלית, ספרות, מקף או קו תחתון בלבד');requireCondition(p||!patient(f.id),'קוד הנתרמת כבר קיים');past(f.opened);if(p)Object.assign(p,f);else state.recipients.push(f);done((p?'עודכן תיק נתרמת ':'נפתח תיק נתרמת ')+f.id)})}
function addDose(id){modal('קליטת מנות זרע',`<div class="notice">לכל מנה ייווצר מזהה נפרד. קליטת יבוא או העברה מתועדת גם ביומן ההעברות. תורם חסום או ללא אישור ייקלט בהסגר.</div><div class="form-grid">${selectField('donor','תורם',donorOpts(),id||'')}${field('count','מספר מנות לקליטה','number',1,true,false,'min="1" max="200" step="1"')}${field('batch','מזהה תרומה / אצווה')}${field('quality','סוג הכנה','text','IUI')}${field('donated','תאריך תרומה','date',today())}${field('frozen','תאריך הקפאה','date',today())}${field('received','תאריך הגעה ליחידה','date',today())}${field('location','מכל / קניסטר / מיקום')}${selectField('recipient','שמירה לנתרמת (אופציונלי)',[['','ללא שמירה'],...patientOpts().slice(1)],'',false)}${field('ref','אסמכתת קליטה / משלוח','text','',false)}${field('note','הערות','textarea','',false,true)}</div>`,f=>{const d=donor(f.donor);requireCondition(d,'יש לבחור תורם');const n=num(f.count);requireCondition(Number.isInteger(n)&&n>=1&&n<=200,'מספר המנות צריך להיות שלם בין 1 ל־200');past(f.received);requireCondition(f.donated<=f.frozen&&f.frozen<=f.received,'סדר התאריכים חייב להיות: תרומה, הקפאה, הגעה');if(d.origin!=='local')requireCondition(f.ref.trim(),'בקליטה מבנק אחר נדרשת אסמכתת משלוח');const ids=[];for(let i=0;i<n;i++){const dose={...f,id:uid('V'),status:!canUse(d)?'quarantine':f.recipient?'reserved':'available'};delete dose.count;delete dose.ref;ids.push(dose.id);state.doses.push(dose)}if(d.origin!=='local')state.transfers.push({id:uid('TR'),donor:d.id,direction:'in',bank:d.bank,date:f.received,ref:f.ref,doseIds:ids,note:f.note});done(`נקלטו ${n} מנות לתורם ${d.id}`)})}
function useForm(id,recipientId){const selectedDose=state.doses.find(x=>x.id===id),dId=selectedDose?.donor||(donor(id)?id:'');const available=state.doses.filter(v=>['available','reserved','quarantine'].includes(v.status)&&(!dId||v.donor===dId));modal('רישום שימוש במנה',`<div class="notice">נרשמת צריכה של מנה בודדת. תורם חסום, אישור חסר או מנה בהסגר ימנעו את השמירה.</div><div class="form-grid">${selectField('dose','מנה',[['','בחירת מנה'],...available.map(v=>[v.id,`${v.id} · ${v.donor} · ${doseStatus[v.status]}${canUse(donor(v.donor))?'':' · שימוש חסום'}`])],selectedDose?.id||'',true,true)}${selectField('recipient','נתרמת',patientOpts(),selectedDose?.recipient||recipientId||'')}${selectField('type','סוג טיפול',[['IUI','IUI · הזרעה'],['IVF','IVF · הפריה חוץ גופית'],['ICSI','ICSI · הזרקת זרע']], 'IUI')}${field('date','תאריך טיפול','date',today())}${field('cycle','מזהה מחזור טיפול')}${field('note','הערות','textarea','',false,true)}${typeof clinicalFormFields==='function'?clinicalFormFields({}):''}</div>`,f=>{const clinical=typeof collectClinical==='function'?collectClinical(f,f.date):{};const v=state.doses.find(x=>x.id===f.dose),d=donor(v?.donor),p=patient(f.recipient);requireCondition(v&&d&&p,'יש לבחור מנה ונתרמת קיימות');requireCondition(canUse(d),d.status==='blocked'?'השימוש נדחה: התורם חסום. יש לתעד החלטת שחרור מוסמכת בכרטיס התורם.':'השימוש נדחה: אין לתורם אישור נוכחי בתוקף');requireCondition(['available','reserved'].includes(v.status),'המנה אינה זמינה לשימוש או נמצאת בהסגר');requireCondition(!state.uses.some(x=>x.dose===v.id),'כבר נרשם שימוש במנה זו');requireCondition(p.status==='active','תיק הנתרמת אינו במצב פעיל');requireCondition(!v.recipient||v.recipient===p.id,'המנה שמורה לנתרמת אחרת');past(f.date,'תאריך הטיפול');requireCondition(f.date>=v.received&&f.date>=v.frozen,'תאריך הטיפול קודם לקליטת המנה או הקפאתה');const blockAtDate=latestDecision(d,f.date);requireCondition(blockAtDate?.decision==='approved'&&blockAtDate.expires>=f.date,'אין אישור בתוקף בתאריך הטיפול שנבחר');requireCondition(blockAtDate?.decision!=='blocked','התורם היה חסום בתאריך הטיפול. אין לרשום שימוש בזמן חסימה');v.status='used';v.recipient=f.recipient;state.uses.push({...f,id:uid('U'),donor:d.id,clinical});done(`נרשם שימוש במנה ${v.id} לנתרמת ${p.id}`)})}
function approvalForm(id,forced){const title=forced==='blocked'?'תיעוד חסימת תורם':'תיעוד החלטה / אישור';modal(title,`<div class="notice">נדרשת אסמכתה שהתקבלה בפועל. הוספת אישור אינה משחררת תורם שכבר חסום. לצורך זה יש מסלול נפרד בכרטיס החסימות.</div><div class="form-grid">${selectField('donor','תורם',donorOpts(),id||'')}${selectField('decision','סוג החלטה',forced?[['blocked','חסימה / מניעת שימוש']]:[['approved','אישור שימוש'],['blocked','חסימה / מניעת שימוש'],['pending','ממתין / הסגר']],forced||'approved')}${field('date','תאריך החלטה','date',today())}${field('received','תאריך קבלת המידע','date',today())}${field('expires','תוקף אישור עד (נדרש לאישור)','date','',false)}${field('ref','מספר מסמך / אסמכתה')}${field('note','סיבה / פירוט ההחלטה','textarea','',true,true)}</div>`,f=>{const d=donor(f.donor);requireCondition(d,'יש לבחור תורם');past(f.date,'תאריך ההחלטה');past(f.received,'תאריך הקבלה');requireCondition(f.received>=f.date,'תאריך קבלה לא יקדם להחלטה');if(f.decision==='approved'){requireCondition(f.expires&&f.expires>=f.date,'יש להזין תוקף אישור שאינו קודם להחלטה');if(d.status!=='blocked')d.status='active'}else if(f.decision==='blocked'){d.status='blocked';d.blockedDate=f.date;d.blockReason=f.note}else if(d.status!=='blocked')d.status='pending';state.approvals.push({...f,id:uid('AP')});state.mohUpdates.push({id:uid('MU'),date:f.received,ref:f.ref,rows:1,note:'תיעוד החלטה ידני · '+d.id});done(`תועדה החלטה ${f.decision==='blocked'?'לחסימת':'לגבי'} תורם ${d.id}`)})}
function unblockForm(id){const d=donor(id);requireCondition(d?.status==='blocked','יש לבחור תורם חסום');modal('תיעוד שחרור חסימה',`<div class="notice bad">שחרור ישפיע על האפשרות לרשום שימוש במנות. יש להזין החלטה מוסמכת ואישור תקף; אין די בהסרת סימון.</div><div class="form-grid">${field('donor','תורם','text',id,true,false,'readonly')}${field('ref','אסמכתת שחרור')}${field('date','תאריך החלטה','date',today())}${field('received','תאריך קבלת ההחלטה','date',today())}${field('expires','תוקף אישור עד','date','')}${field('note','נימוק וזהות הגורם המאשר','textarea','',true,true)}<label class="check-label field wide"><input type="checkbox" name="confirmed" required>בדקתי החלטה המאפשרת שחרור מהחסימה ורשמתי את האסמכתה</label></div>`,f=>{past(f.date);past(f.received);requireCondition(f.date>=d.blockedDate,'החלטת השחרור קודמת לחסימה');requireCondition(f.received>=f.date,'תאריך הקבלה קודם להחלטה');requireCondition(f.expires>=today()&&f.expires>=f.date,'נדרש אישור בתוקף');requireCondition(f.confirmed,'נדרש אישור בדיקה');state.approvals.push({...f,id:uid('AP'),decision:'approved',release:true});d.status='active';d.blockReason='';d.blockedDate='';done(`תועד שחרור חסימה לתורם ${id} לפי אסמכתה ${f.ref}`)})}
function transferForm(id){modal('תיעוד העברה בין בנקים',`<div class="notice">טופס זה מעביר מנות קיימות החוצה. קליטה מבנק אחר מתבצעת דרך ״קליטת מנות״ כדי ליצור מזהי מנות חדשים.</div><div class="form-grid">${selectField('donor','תורם',donorOpts(),id||'')}${field('bank','בנק יעד')}${field('date','תאריך העברה','date',today())}${field('ref','אסמכתת העברה')}${field('doseIds','מזהי מנות להעברה, מופרדים בפסיק','textarea','',true,true)}${field('note','פרטי משלוח / איש קשר לדוגמה','textarea','',false,true)}</div>`,f=>{const d=donor(f.donor);requireCondition(canUse(d),'אין להעביר החוצה מנות מתורם חסום או ללא אישור בתוקף');const ids=f.doseIds.split(/[\s,;]+/).filter(Boolean);requireCondition(ids.length&&new Set(ids).size===ids.length,'יש לציין מזהי מנות ייחודיים');past(f.date);const selected=ids.map(id=>state.doses.find(v=>v.id===id));selected.forEach(v=>{requireCondition(v&&v.donor===d.id,'כל המנות חייבות להיות קיימות ושייכות לתורם');requireCondition(v.status==='available'&&!v.recipient,'ניתן להעביר רק מנות זמינות שאינן שמורות');requireCondition(f.date>=v.received,'תאריך ההעברה קודם לקליטת מנה')});selected.forEach(v=>v.status='transferred');state.transfers.push({...f,id:uid('TR'),direction:'out',doseIds:ids});done(`הועברו ${ids.length} מנות מתורם ${d.id} אל ${f.bank}`)})}
function embryoForm(id,editId){const e=editId?state.embryos.find(x=>x.id===editId):null;modal(e?'עדכון מלאי עוברים':'רישום אצוות עוברים',`<div class="notice">מלאי מדווח ולא הוראת טיפול. כל רשומה מייצגת אצווה ממחזור טיפול אחד. תורם חסום יסומן לבירור; אין לשנות מספרים ללא תיעוד.</div><div class="form-grid">${selectField('donor','תורם',donorOpts(),e?.donor||id||'')}${selectField('recipient','נתרמת',patientOpts(),e?.recipient||'')}${field('cycle','מזהה מחזור IVF / ICSI','text',e?.cycle||'')}${field('date','תאריך הקפאת עוברים','date',e?.date||today())}${field('created','מספר שהוקפאו בתחילה','number',e?.created||1,true,false,'min="1" step="1"')}${field('used','מספר שנוצלו עד היום','number',e?.used||0,true,false,'min="0" step="1"')}${field('discarded','מספר שהושמדו','number',e?.discarded||0,true,false,'min="0" step="1"')}${field('location','מיקום בהקפאה','text',e?.location||'')}${field('note','מקור מידע / נימוק לעדכון','textarea',e?.note||'',true,true)}</div>`,f=>{const d=donor(f.donor),p=patient(f.recipient);requireCondition(d&&p,'תורם או נתרמת לא נמצאו');past(f.date);const vals=['created','used','discarded'];vals.forEach(k=>{f[k]=num(f[k]);requireCondition(Number.isInteger(f[k])&&f[k]>=0,'יש להזין מספרים שלמים לא שליליים')});requireCondition(f.created>0&&f.used+f.discarded<=f.created,'מספר שנוצלו והושמדו אינו יכול לעלות על המספר שהוקפא');requireCondition(!state.embryos.some(x=>x.id!==e?.id&&x.donor===f.donor&&x.recipient===f.recipient&&x.cycle===f.cycle),'כבר קיימת אצווה למחזור הזה. יש לעדכן את הרשומה הקיימת');if(e)Object.assign(e,f);else state.embryos.push({...f,id:uid('E')});done(`${e?'עודכן מלאי':'נרשמו'} עוברים לתורם ${d.id}, נתרמת ${p.id}`)})}
function birthForm(id,editId){const b=editId?state.births.find(x=>x.id===editId):null;modal(b?'עדכון דיווח בריאותי':'רישום לידה ומידע בריאותי',`<div class="notice">רשומה אחת לכל ילד/ה; בלידת תאומים יש להזין שתי רשומות. ״לא ידוע״ אינו מעיד על בריאות תקינה. אין להזין פרטים מזהים אמיתיים.</div><div class="form-grid">${selectField('donor','תורם',donorOpts(),b?.donor||id||'')}${selectField('recipient','נתרמת',patientOpts(),b?.recipient||'')}${field('date','תאריך לידה','date',b?.date||today())}${field('reported','תאריך קבלת הדיווח','date',b?.reported||today())}${field('cycle','מזהה מחזור טיפול / אסמכתת מקור','text',b?.cycle||'')}${selectField('health','מצב מידע רפואי',Object.entries(health),b?.health||'unknown')}${field('note','מקור הדיווח ופירוט רפואי לדוגמה','textarea',b?.note||'',true,true)}</div>`,f=>{requireCondition(donor(f.donor)&&patient(f.recipient),'יש לבחור תורם ונתרמת');past(f.date,'תאריך הלידה');past(f.reported,'תאריך הדיווח');requireCondition(f.reported>=f.date,'דיווח לא יקדם ללידה');if(b)Object.assign(b,f);else state.births.push({...f,id:uid('CH')});done(`${b?'עודכן דיווח בריאותי':'נרשמה לידה'} מתורם ${f.donor} לנתרמת ${f.recipient}`)})}
function paymentForm(id){modal('רישום תשלום לתורם',`<div class="form-grid">${selectField('donor','תורם מקומי',donorOpts(true),id||'')}${field('date','תאריך תשלום','date',today())}${field('amount','סכום בש״ח','number','',true,false,'min="0.01" step="0.01"')}${field('session','מזהה מפגש תרומה / אצווה')}${field('ref','אסמכתת תשלום')}${field('note','הערות','textarea','',false,true)}</div>`,f=>{requireCondition(donor(f.donor)?.origin==='local','תשלום לתורם אפשר לרשום רק לתורם מקומי');past(f.date);f.amount=num(f.amount);requireCondition(f.amount>0,'הסכום חייב להיות חיובי');state.payments.push({...f,id:uid('P')});done(`נרשם תשלום ${money(f.amount)} לתורם ${f.donor}`)})}
function recipientDetail(id){const p=patient(id);if(!p)return;modal(`תיק נתרמת ${esc(id)}`,`<div class="kv-grid"><div><div class="kv-label">שם הדגמה</div><div class="kv-value">${esc(p.name)}</div></div><div><div class="kv-label">מצב תיק</div>${badge(recStatus[p.status])}</div><div><div class="kv-label">נפתח</div>${fmt(p.opened)}</div></div><h3 class="subheading">טיפולים ומנות</h3>${useTable(state.uses.filter(x=>x.recipient===id))}<h3 class="subheading">מנות שמורות</h3>${table(['מנה','תורם','הקפאה','סטטוס'],state.doses.filter(x=>x.recipient===id&&x.status==='reserved').map(x=>[esc(x.id),esc(x.donor),fmt(x.frozen),donorStatus(donor(x.donor))]))}<h3 class="subheading">עוברים מוקפאים</h3>${embryoTable(state.embryos.filter(x=>x.recipient===id))}<h3 class="subheading">לידות ומידע בריאותי</h3>${birthTable(state.births.filter(x=>x.recipient===id))}`,null);bindOverlayActions()}
function bindOverlayActions(){$$('#overlay [data-action]').forEach(b=>b.onclick=()=>{const {action,id}=b.dataset;closeModal();act(action,id)})}
function download(name,data,type='text/plain'){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('הקובץ הוכן להורדה')}
function csv(name,headers,rows){const clean=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download(name+'_'+today()+'.csv','\uFEFF'+[headers,...rows].map(r=>r.map(clean).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function period(){const from=$('#reportFrom')?.value||today().slice(0,4)+'-01-01',to=$('#reportTo')?.value||today();requireCondition(validDate(from)&&validDate(to)&&from<=to,'טווח התאריכים אינו תקין');return rows=>rows.filter(r=>r.date>=from&&r.date<=to)}
function exportReport(action){const between=period();if(action==='exportDonors'||action==='exportSummary')csv('donors',['קוד תורם','כינוי','מקור','בנק מקור','קוד חיצוני','סטטוס','אישור נוכחי בתוקף','תאריך אישור','תוקף עד','תאריך חסימה','מנות שנקלטו','מנות נותרות ביחידה','השתמשו בתורם בעבר','נתרמות עדיין בטיפול','עוברים מוקפאים'],state.donors.map(d=>[d.id,d.alias,orig[d.origin],d.bank,d.external,d.status,canUse(d)?'כן':'לא',currentApproval(d)?.date,currentApproval(d)?.expires,d.blockedDate,ds(d.id).length,blockedImpact(d).doses,historicCount(d.id),countRecipients(d.id,true),em(d.id).reduce((a,e)=>a+frozen(e),0)]));
 if(action==='exportUses')csv('treatments',['תאריך','קוד תורם','קוד נתרמת','מנה','הקפאה','טיפול','מחזור'],between(state.uses).map(u=>[u.date,u.donor,u.recipient,u.dose,state.doses.find(v=>v.id===u.dose)?.frozen,u.type,u.cycle]));
 if(action==='exportBlocks')csv('blocked_donors',['תורם','תאריך חסימה','סיבה','מנות מושפעות','נתרמות קשורות','עוברים קפואים'],state.donors.filter(d=>d.status==='blocked').map(d=>{const k=blockedImpact(d);return[d.id,d.blockedDate,d.blockReason,k.doses,k.recipients,k.embryos]}));
 if(action==='exportEmbryos')csv('frozen_embryos',['תורם','נתרמת','מחזור','תאריך הקפאה','הוקפאו','נוצלו','הושמדו','נותרו','מיקום','חסימת תורם'],state.embryos.map(e=>[e.donor,e.recipient,e.cycle,e.date,e.created,e.used,e.discarded,frozen(e),e.location,donor(e.donor)?.status==='blocked'?'חסום':'לא חסום']));
 if(action==='exportBirths')csv('births',['מזהה רשומה','תאריך לידה','תורם','נתרמת','מחזור','מידע בריאותי','תאריך דיווח','פירוט'],between(state.births).map(b=>[b.id,b.date,b.donor,b.recipient,b.cycle,health[b.health],b.reported,b.note]));
 if(action==='exportPayments')csv('payments',['תאריך','תורם','סכום בשח','מפגש','אסמכתה','הערות'],between(state.payments).map(p=>[p.date,p.donor,p.amount,p.session,p.ref,p.note]));
 if(action==='exportTransfers')csv('transfers',['תאריך','תורם','כיוון','בנק','מנות','אסמכתה','הערות'],between(state.transfers).map(t=>[t.date,t.donor,t.direction,t.bank,t.doseIds.join(' | '),t.ref,t.note]));
 if(action==='exportAudit')csv('activity_log',['מועד','פעולה','מבצע'],state.audit.map(a=>[a.time,a.action,a.by]));}
function csvParse(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(c=>c.trim()))rows.push(row);row=[];cell=''}else cell+=c}requireCondition(!quoted,'קובץ CSV מכיל מרכאות לא סגורות');if(cell||row.length){row.push(cell);rows.push(row)}requireCondition(rows.length>1,'הקובץ חייב להכיל כותרות ולפחות רשומה אחת');const head=rows.shift().map(c=>c.trim());requireCondition(new Set(head).size===head.length,'קיימות כותרות כפולות');return rows.map((r,i)=>{requireCondition(r.length===head.length,'מספר עמודות לא תקין בשורה '+(i+2));return Object.fromEntries(head.map((k,j)=>[k,r[j].trim()]))})}
function validateMoh(rows){requireCondition(rows.length<=500,'עד 500 רשומות לקובץ');const keys=['donor_code','decision','decision_date','received_date','reference','reason','expires'];rows.forEach((r,i)=>{requireCondition(keys.every(k=>Object.hasOwn(r,k)),'יש להשתמש בכותרות של קובץ התבנית');requireCondition(donor(r.donor_code),'קוד תורם לא קיים בשורה '+(i+2)+': '+r.donor_code);requireCondition(['blocked','pending','approved'].includes(r.decision),'החלטה אינה תקינה בשורה '+(i+2));requireCondition(validDate(r.decision_date)&&validDate(r.received_date),'תאריך לא תקין בשורה '+(i+2));past(r.decision_date);past(r.received_date);requireCondition(r.received_date>=r.decision_date,'תאריך הקבלה קודם להחלטה');requireCondition(r.reference&&r.reason,'נדרשים אסמכתה ונימוק בכל שורה');if(r.decision==='approved')requireCondition(validDate(r.expires)&&r.expires>=r.decision_date,'נדרש תוקף תקין לאישור');requireCondition(!state.approvals.some(a=>a.donor===r.donor_code&&a.ref===r.reference&&a.decision===r.decision),'החלטה זו כבר תועדה: '+r.reference)});requireCondition(new Set(rows.map(r=>[r.donor_code,r.reference,r.decision].join('|'))).size===rows.length,'קיימות החלטות כפולות בקובץ');return rows}
function mohImport(){mohPreview=null;modal('קליטת עדכון משרד הבריאות',`<div class="notice">בחרו קובץ CSV שהכנתם מעדכון מאומת. יש להתאים קוד תורם פנימי לכל שורה. אישור בקובץ אינו משחרר תורם חסום; שחרור דורש תיעוד נפרד.</div><button class="btn small" type="button" id="mohTemplate">${icon('download',15)}הורדת תבנית CSV</button><div class="field wide" style="margin-top:20px"><label for="mohFile">בחירת קובץ CSV</label><input type="file" id="mohFile" accept=".csv,text/csv" required><small>תאריכים בפורמט YYYY-MM-DD. החלטות: blocked, pending, approved. עד 2MB.</small></div><div id="mohPreview"></div><label class="check-label" style="margin-top:20px"><input type="checkbox" name="verified" required>בדקתי את מקור העדכון, התאמת התורמים והאסמכתאות לפני הקליטה</label>`,f=>{requireCondition(mohPreview?.length,'יש לבחור קובץ תקין ולבדוק את התצוגה המקדימה');requireCondition(f.verified,'נדרש אישור בדיקת העדכון');const rows=validateMoh(mohPreview); // Validate the entire import before any mutation.
 const blockedInBatch=new Set(rows.filter(r=>r.decision==='blocked').map(r=>r.donor_code));
 rows.forEach(r=>{const d=donor(r.donor_code);state.approvals.push({id:uid('AP'),donor:d.id,decision:r.decision,date:r.decision_date,received:r.received_date,expires:r.expires,ref:r.reference,note:r.reason});if(r.decision==='blocked'){d.status='blocked';d.blockedDate=r.decision_date;d.blockReason=r.reason}else if(d.status!=='blocked'&&!blockedInBatch.has(d.id))d.status=r.decision==='approved'?'active':'pending'});state.mohUpdates.push({id:uid('MU'),date:today(),ref:[...new Set(rows.map(r=>r.reference))].join(', '),rows:rows.length,note:'ייבוא CSV שנבדק ידנית'});done(`נקלט עדכון של ${rows.length} החלטות`)},'תיעוד מקור ואימות לפני שינוי סטטוס');$('#mohTemplate').onclick=()=>csv('moh_update_template',['donor_code','decision','decision_date','received_date','reference','reason','expires'],[['BZ-1042','blocked',today(),today(),'DEMO-REF-NEW','סיבת חסימה לדוגמה','']]);$('#mohFile').onchange=async e=>{mohPreview=null;$('#mohPreview').innerHTML='';try{const f=e.target.files[0];requireCondition(f&&f.size<=2*1024*1024,'יש לבחור קובץ עד 2MB');const rows=validateMoh(csvParse(await f.text()));mohPreview=rows;$('#formError').hidden=true;$('#mohPreview').innerHTML=`<div class="preview-box">${table(['תורם','החלטה','תאריך','אסמכתה'],rows.map(r=>[esc(r.donor_code),esc(r.decision),fmt(r.decision_date),esc(r.reference)]))}</div><p class="label-note">${rows.length} החלטות מוכנות לקליטה לאחר בדיקה.</p>`}catch(err){$('#formError').hidden=false;$('#formError').textContent=err.message}}}
function validateBackup(s){requireCondition(s&&s.schema===1,'גרסת הגיבוי אינה נתמכת');requireCondition(s.settings&&typeof s.settings.institution==='string'&&typeof s.settings.unit==='string'&&/^#[0-9a-f]{6}$/i.test(s.settings.accent),'הגדרות גיבוי אינן תקינות');const arrays=['donors','recipients','doses','uses','embryos','births','payments','transfers','approvals','audit','mohUpdates'];for(const k of arrays){requireCondition(Array.isArray(s[k])&&s[k].length<=20000,'מבנה שדה לא תקין: '+k);requireCondition(s[k].every(x=>x&&typeof x==='object'&&!Array.isArray(x)&&typeof x.id==='string'),'רשומה לא תקינה: '+k);requireCondition(new Set(s[k].map(x=>x.id)).size===s[k].length,'מזהים כפולים: '+k)}const dIds=new Set(s.donors.map(d=>d.id)),pIds=new Set(s.recipients.map(p=>p.id)),vMap=new Map(s.doses.map(v=>[v.id,v]));for(const k of ['doses','uses','embryos','births','payments','transfers','approvals'])for(const r of s[k])requireCondition(dIds.has(r.donor),'הפניה לתורם חסר ב־'+k);for(const k of ['uses','embryos','births'])for(const r of s[k])requireCondition(pIds.has(r.recipient),'הפניה לנתרמת חסרה ב־'+k);for(const d of s.donors){requireCondition(/^[A-Za-z0-9_-]{2,40}$/.test(d.id)&&typeof d.alias==='string'&&typeof d.bank==='string'&&typeof d.external==='string','פרטי תורם אינם תקינים');requireCondition(['local','import','transfer'].includes(d.origin)&&['active','blocked','pending'].includes(d.status),'מצב תורם אינו תקין');if(d.status==='blocked')requireCondition(validDate(d.blockedDate)&&d.blockReason,'חסימה ללא סיבה או תאריך')}
 for(const p of s.recipients)requireCondition(['active','paused','completed'].includes(p.status)&&typeof p.name==='string','פרטי נתרמת אינם תקינים');for(const v of s.doses){requireCondition(Object.hasOwn(doseStatus,v.status)&&validDate(v.frozen)&&validDate(v.received)&&v.frozen<=v.received,'נתוני מנה אינם תקינים');requireCondition(!v.recipient||pIds.has(v.recipient),'נתרמת חסרה בשיוך מנה')}
 requireCondition(new Set(s.uses.map(u=>u.dose)).size===s.uses.length,'שימוש כפול באותה מנה');for(const u of s.uses){const v=vMap.get(u.dose);requireCondition(v&&v.donor===u.donor&&v.status==='used'&&v.recipient===u.recipient&&validDate(u.date)&&u.date>=v.received,'קשר טיפול–מנה אינו תקין');requireCondition(['IUI','IVF','ICSI'].includes(u.type),'סוג טיפול אינו תקין')}
 for(const e of s.embryos)requireCondition(['created','used','discarded'].every(k=>Number.isInteger(e[k])&&e[k]>=0)&&e.created>0&&frozen(e)>=0&&validDate(e.date),'מלאי עוברים אינו תקין');for(const a of s.approvals)requireCondition(['approved','blocked','pending'].includes(a.decision)&&validDate(a.date)&&validDate(a.received)&&(a.decision!=='approved'||validDate(a.expires))&&typeof a.ref==='string','החלטה לא תקינה');for(const b of s.births)requireCondition(validDate(b.date)&&validDate(b.reported)&&Object.hasOwn(health,b.health),'דיווח לידה אינו תקין');for(const p of s.payments)requireCondition(Number.isFinite(p.amount)&&p.amount>0&&validDate(p.date),'תשלום אינו תקין');for(const t of s.transfers)requireCondition(['in','out'].includes(t.direction)&&validDate(t.date)&&Array.isArray(t.doseIds)&&t.doseIds.every(id=>vMap.get(id)?.donor===t.donor),'העברה אינה תקינה');return s}
function restore(){let candidate=null;modal('שחזור גיבוי מלא',`<div class="notice bad">השחזור יחליף את כל הרשומות וההגדרות בדפדפן זה. מומלץ לייצא גיבוי נוכחי לפני ההחלפה.</div><div class="field"><label for="restoreFile">קובץ גיבוי JSON של המערכת</label><input id="restoreFile" type="file" accept=".json,application/json" required><small>עד 10MB. הגיבוי נבדק לפני החלפת הנתונים.</small></div><div id="restorePreview" class="help-text"></div><label class="check-label"><input type="checkbox" name="replace" required>אני מאשר החלפה של כל נתוני ההדגמה המקומיים</label>`,f=>{requireCondition(candidate&&f.replace,'יש לבחור גיבוי תקין ולאשר החלפה');state=validateBackup(candidate);view='dashboard';selected=null;done('שוחזר גיבוי מלא','הגיבוי שוחזר בהצלחה')});$('#restoreFile').onchange=async e=>{candidate=null;try{const f=e.target.files[0];requireCondition(f&&f.size<=10*1024*1024,'הקובץ צריך להיות עד 10MB');candidate=validateBackup(JSON.parse(await f.text()));$('#restorePreview').textContent=`הגיבוי מכיל ${candidate.donors.length} תורמים, ${candidate.recipients.length} נתרמות ו־${candidate.doses.length} מנות.`;$('#formError').hidden=true}catch(err){$('#formError').hidden=false;$('#formError').textContent=err.message}}}
function help(){modal('אודות זרע',`<p class="help-text">אב־טיפוס ראשוני לניהול בנק זרע בבית חולים, המבוסס על תהליך העבודה שתיארת. כל הרשומות, התורמים, האישורים והבנקים בנתוני ההדגמה הם סינתטיים.</p><h3 class="subheading">הגדרות המדדים</h3><ul class="list-bullet"><li>״השתמשו בתורם״ — מספר נתרמות ייחודיות עם טיפול מתועד.</li><li>״עדיין בטיפול״ — תיקי נתרמות פעילים עם שימוש, מנה שמורה או עוברים מוקפאים מהתורם.</li><li>״מנות ביחידה״ — מנות זמינות, שמורות או בהסגר; ללא מנות שנוצלו או הועברו החוצה.</li><li>״עוברים מוקפאים״ — הוקפאו בתחילה פחות נוצלו ופחות הושמדו.</li><li>המספרים מקומיים ואינם מונים שימושים בבנקים אחרים או במאגר ארצי.</li></ul><h3 class="subheading">מקורות לעיון ולאפיון מוסדי</h3><div class="source-list"><a href="https://www.gov.il/he/service/receiving-donor-sperm" target="_blank" rel="noopener">משרד הבריאות — קבלת תרומת זרע</a><br><a href="https://www.gov.il/he/service/sperm-donation" target="_blank" rel="noopener">משרד הבריאות — מתן תרומת זרע</a><br><a href="https://www.gov.il/he/pages/med-inst-sperm_bank?chapterindex=1" target="_blank" rel="noopener">משרד הבריאות — רישוי בנקי זרע</a></div><p class="label-note">המקורות משמשים לעיון. הגרסה אינה אישור עמידה בדרישות רגולטוריות ואינה כוללת חיבור למערכות משרד הבריאות. נבדקו לצורך האפיון: 25.11.2026.</p>`,null,'מערכת הדגמה · גרסה 0.2')}
function act(action,id){try{if(action.startsWith('export'))return exportReport(action);switch(action){case'donor':closeModal();return openDonor(id);case'backDonors':return go('donors');case'addDonor':return donorForm();case'editDonor':return donorForm(id);case'addRecipient':return recipientForm();case'editRecipient':return recipientForm(id);case'recipientDetail':return recipientDetail(id);case'addDose':return addDose(id);case'manageDose':return manageDose(id);case'use':return useForm(id);case'addApproval':return approvalForm(id);case'block':return approvalForm(id,'blocked');case'unblock':return unblockForm(id);case'addTransfer':return transferForm(id);case'addEmbryo':return embryoForm(id);case'editEmbryo':return embryoForm(null,id);case'addBirth':return birthForm(id);case'editBirth':return birthForm(null,id);case'addPayment':return paymentForm(id);case'mohImport':return mohImport();case'reveal':reveal=!reveal;save('הוצגו / הוסתרו פרטי הדגמה חסויים לתורם '+selected);return;case'help':return help();case'menu':$('.sidebar').classList.toggle('open');return;case'print':window.print();return;case'backup':return download('zera_backup_'+today()+'.json',JSON.stringify(state,null,2),'application/json');case'restore':return restore();case'reset':modal('איפוס סביבת ההדגמה','<div class="notice bad">כל הנתונים שהזנת בדפדפן יוחלפו בנתוני הפתיחה. ניתן לייצא גיבוי קודם לכן.</div><label class="check-label"><input type="checkbox" required name="reset">אני מאשר למחוק את הנתונים המקומיים ולשחזר נתוני הדגמה</label>',f=>{if(f.reset){state=seed();go('dashboard');done('אופסו נתוני ההדגמה')}});return;case'periodSummary':{const between=period(),u=between(state.uses),b=between(state.births),p=between(state.payments),t=between(state.transfers);$('#periodResult').innerHTML=`<div class="detail-body"><div class="kv-grid"><div><div class="kv-label">טיפולים בתקופה</div><div class="kv-value">${u.length} · ${new Set(u.map(x=>x.recipient)).size} נתרמות ייחודיות</div></div><div><div class="kv-label">לידות מתועדות</div><div class="kv-value">${b.length} ילדים</div></div><div><div class="kv-label">תשלומים בתקופה</div><div class="kv-value">${money(p.reduce((a,x)=>a+x.amount,0))}</div></div><div><div class="kv-label">העברות נכנסות</div><div class="kv-value">${t.filter(x=>x.direction==='in').reduce((a,x)=>a+x.doseIds.length,0)} מנות</div></div><div><div class="kv-label">העברות יוצאות</div><div class="kv-value">${t.filter(x=>x.direction==='out').reduce((a,x)=>a+x.doseIds.length,0)} מנות</div></div></div></div>`;return}}}catch(err){toast(err.message)}}
function bind(){ $$('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));$$('[data-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();act(b.dataset.action,b.dataset.id)});$$('[data-tab]').forEach(b=>b.onclick=()=>{detailTab=b.dataset.tab;reveal=false;render()});const updateDonors=()=>{filters.q=$('#search')?.value||'';filters.status=$('#statusFilter')?.value||'';filters.origin=$('#originFilter')?.value||'';$('#donorTable').outerHTML=donorTable(view==='dashboard');$$('#donorTable [data-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();act(b.dataset.action,b.dataset.id)})};if($('#search'))$('#search').oninput=updateDonors;if($('#statusFilter'))$('#statusFilter').onchange=updateDonors;if($('#originFilter'))$('#originFilter').onchange=updateDonors;const updateDoses=()=>{const q=$('#doseSearch').value.toLowerCase(),status=$('#doseStatus').value;$('#doseResults').innerHTML=dosesTable(state.doses.filter(v=>(!status||v.status===status)&&[v.id,v.donor,v.batch,v.location].some(x=>String(x).toLowerCase().includes(q))));$$('#doseResults [data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action,b.dataset.id))};if($('#doseSearch'))$('#doseSearch').oninput=updateDoses;if($('#doseStatus'))$('#doseStatus').onchange=updateDoses;if($('#settingsForm'))$('#settingsForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!/^#[0-9a-f]{6}$/i.test(f.accent))return;state.settings=f;save('עודכנו פרטי היחידה ועיצוב');toast('ההתאמות נשמרו')};}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#overlay .modal')){const focusable=$$('#overlay button,#overlay input,#overlay select,#overlay textarea,#overlay a').filter(x=>!x.disabled),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();
function manageDose(id){const v=state.doses.find(x=>x.id===id);requireCondition(v&&['available','reserved','quarantine'].includes(v.status),'לא ניתן לשנות מנה שנוצלה, הושמדה או הועברה');modal('ניהול מנה '+esc(id),`<div class="notice">תאריך הקפאה ומקור המנה נשמרים. שחרור מהסגר אפשרי רק עם אישור תורם תקף ותיעוד בדיקה. השמדה היא שינוי מצב מתועד ואינה מוחקת את המנה.</div><div class="form-grid">${selectField('status','מצב חדש',[['available','זמינה'],['reserved','שמורה לנתרמת'],['quarantine','בהסגר'],['discarded','הושמדה']],v.status)}${selectField('recipient','נתרמת (נדרשת למנה שמורה)',[['','ללא שיוך'],...patientOpts().slice(1)],v.recipient||'',false)}${field('location','מיקום','text',v.location)}${field('reason','סיבה ואסמכתה לשינוי','textarea','',true,true)}</div>`,f=>{requireCondition(['available','reserved','quarantine'].includes(v.status),'מצב המנה השתנה');if(['available','reserved'].includes(f.status))requireCondition(canUse(donor(v.donor)),'אין לשחרר מנה מתורם חסום או ללא אישור תקף');if(f.status==='reserved')requireCondition(patient(f.recipient)?.status==='active','יש לבחור נתרמת עם תיק פעיל');const before=v.status;v.status=f.status;v.recipient=f.status==='reserved'?f.recipient:f.status==='quarantine'?v.recipient:'';v.location=f.location;v.note=(v.note?v.note+'\n':'')+today()+': '+f.reason;done(`עודכנה מנה ${id}: ${before} → ${f.status}. ${f.reason}`)})}
